CREATE TABLE IF NOT EXISTS replenishment_policy(policy_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,location_id TEXT NOT NULL,material_master_id TEXT NOT NULL,supplier_id TEXT,min_qty NUMERIC NOT NULL DEFAULT 0,max_qty NUMERIC NOT NULL DEFAULT 0,reorder_point NUMERIC NOT NULL DEFAULT 0,safety_stock NUMERIC NOT NULL DEFAULT 0,lead_time_days INTEGER NOT NULL DEFAULT 0,order_multiple NUMERIC NOT NULL DEFAULT 1,uom TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,location_id,material_master_id,supplier_id));
CREATE TABLE IF NOT EXISTS replenishment_suggestions(suggestion_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,location_id TEXT NOT NULL,material_master_id TEXT NOT NULL,supplier_id TEXT,source_mrp_run_id TEXT,policy_id TEXT,on_hand NUMERIC NOT NULL,open_po_qty NUMERIC NOT NULL DEFAULT 0,mrp_shortage_qty NUMERIC NOT NULL DEFAULT 0,reorder_point NUMERIC NOT NULL DEFAULT 0,safety_stock NUMERIC NOT NULL DEFAULT 0,suggested_qty NUMERIC NOT NULL,uom TEXT NOT NULL,required_date TEXT,status TEXT NOT NULL DEFAULT 'SUGGESTED',notes TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS replenishment_requisitions(requisition_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,location_id TEXT NOT NULL,source_run_id TEXT,status TEXT NOT NULL DEFAULT 'DRAFT',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_replenishment_scope ON replenishment_policy(organization_id,entity_id,location_id,material_master_id,active);
